class L3SyntheticWanConnection(ForwardModel):
    model_config = ConfigDict(
        extra="allow",
        populate_by_name=True,
    )
    advertises_default_route: Annotated[bool | None, Field(alias="advertisesDefaultRoute")] = None
    """
    Whether the CE advertises the default route. Defaults to `false`.

    Note: This property is only used if `subnetAutoDiscovery` is `IP_ROUTES`, which should be the case when BGP
    collection is not enabled on the CE. If the Adj-RIB-Out is not collected, the RIB is examined and a default
    route forwarded out `gatewayPort` is skipped if this property is false.
    """
    backdoor_link_ports: Annotated[list[DevicePort] | None, Field(alias="backdoorLinkPorts")] = None
    """
    L3 interfaces that provide backdoor connectivity between sites.
    """
    gateway_port: Annotated[
        DevicePort | None,
        Field(alias="gatewayPort", examples=[{"device": "nyc-rtr-01", "port": "vlan100"}]),
    ] = None
    """
    The virtual gateway port, if different than `uplinkPort`.
    """
    name: str | None = None
    """
    An optional name for this connection, which will be used as the interface name created on the synthetic
    device that links to the physical edge port.
    """
    peer_ips: Annotated[list[str] | None, Field(alias="peerIps", examples=[["1.1.1.1"]])] = None
    """
    IP addresses of BGP peers to which this connection’s site subnets are advertised. If empty, routes
    advertised to all BGP peers are examined.

    Note: This set is only used if `subnetAutoDiscovery` is `BGP_ROUTES`.
    """
    site: str | None = None
    """
    An optional name for the site in which this connection's gateway device resides. A site is a collection of
    devices that redistribute routes learned from the synthetic device to each other. Grouping connections
    together into a single site enables more accurate site subnet autodiscovery when using `IP_ROUTES` or
    `BGP_ROUTES`.
    """
    subnet_auto_discovery: Annotated[
        AutoDiscoverySource | None, Field(alias="subnetAutoDiscovery", examples=["NONE"])
    ] = None
    """
    The types of routes from which advertised subnets are automatically inferred in the gateway device’s routing
    table. Defaults to `NONE`. If `INTERFACE_ADDRESSES`, the gateway port’s IP address is used. If `IP_ROUTES`,
    subnets are inferred from the gateway device’s RIB. If `BGP_ROUTES`, subnets are inferred from the gateway
    device’s Adj-RIB-Out.

    Note: If not `NONE`, routes are created on the synthetic device for both autodiscovered subnets, as well any
    subnets specified in `subnets`, that are received by another CE.

    Note: Using `BGP_ROUTES` will automatically enable collection of Adj-RIB-Out from the gateway device in
    future network collections.
    """
    subnets: Annotated[list[str] | None, Field(examples=[["123.223.47.0/24"]])] = None
    """
    Advertised subnets. Routes for these subnets are created on the synthetic device if received by another CE.
    Required (and must not be empty) if `subnetAutoDiscovery` is `NONE`.
    """
    uplink_port: Annotated[
        DevicePort, Field(alias="uplinkPort", examples=[{"device": "nyc-rtr-01", "port": "eth1/1"}])
    ]
    """
    The physical uplink port on the edge device.
    """
    vlan: Annotated[int | None, Field(examples=[100])] = None
    """
    The VLAN of traffic from `uplinkPort`, if tagged.
    """
    vrf: str | None = None
    """
    An optional name for the VRF on the synthetic device under which this connection resides.
    """


