class SnmpEndpointProfileDef(ForwardModel):
    model_config = ConfigDict(
        extra="allow",
        populate_by_name=True,
    )
    custom_oids: Annotated[
        list[CustomOid] | None,
        Field(
            alias="customOids",
            examples=[
                [
                    {"name": "system_desc", "oid": "1.3.6.1.2.1.1.1"},
                    {"name": "hostname", "oid": "1.3.6.1.2.1.1.5"},
                ]
            ],
        ),
    ] = None
    """
    Additional OIDs to collect from network endpoints with this profile. The output of each OID is saved to a
    file with the associated name.
    """
    detector_oid: Annotated[
        str | None, Field(alias="detectorOid", examples=["1.3.6.1.2.1.1.1.0"])
    ] = None
    """
    OID to collect to detect a network endpoint of this type. If absent, the profile can be manually assigned to
    a network endpoint, but not auto-detected.
    """
    detector_patterns: Annotated[
        list[str] | None, Field(alias="detectorPatterns", examples=[["ESXi"]])
    ] = None
    """
    Patterns matching on output of `detectorOid` to determine whether the device is of this type. Absent if
    `detectorOid` is absent. Never empty.
    """
    name: Annotated[str, Field(examples=["esxi_snmp"])]
    """
    Name of this profile ("HpPrinter", "SamsungTV", etc.).
    """
    name_detector_oid: Annotated[
        str | None, Field(alias="nameDetectorOid", examples=["1.3.6.1.2.1.1.5"])
    ] = None
    """
    OID to collect to detect the name of a network endpoint of this type. If absent, the name cannot be
    detected.
    """
    name_detector_patterns: Annotated[
        list[str] | None, Field(alias="nameDetectorPatterns", examples=[["FQDN:*enabled"]])
    ] = None
    """
    Glob patterns used to extract the device name from the collected value for `nameDetectorOid`. The word
    immediately after a matched glob pattern is the desired name. If no glob patterns are specified, the first
    word/token in the `nameDetectorOid` value will be used.
    """
    oid_sets: Annotated[
        list[Literal["STANDARD"]] | None, Field(alias="oidSets", examples=[["STANDARD"]])
    ] = None
    """
    Predefined OID sets to collect from network endpoints with this profile. The "STANDARD" set includes OIDs
    for system name, system description, TCP info, UDP info, host address, and interface info.
    """
    response_timeout_sec: Annotated[
        int | None, Field(alias="responseTimeoutSec", examples=[10])
    ] = None
    """
    Timeout in seconds for retrieving the value of one of this profile’s OIDs during discovery or collection.
    Defaults to 5.
    """
    type: Literal["SNMP"]


