    """
    Whether to collect from this network endpoint. Defaults to true.
    """
    credential_id: Annotated[str | None, Field(alias="credentialId", examples=["S-1"])] = None
    """
    The `id` of an SnmpCredential. Credential auto-association will be attempted using credentials configured to
    allow it if this property is unspecified and collecting from this endpoint requires this kind of credential.
    """
