    discovered_cli_credential3_id: Annotated[
        str | None, Field(alias="discoveredCliCredential3Id", examples=["EM-3"])
    ] = None
    """
    The `id` of the working CliCredential of type `EXPERT_MODE` (for Checkpoint devices) auto-discovered during
    the connectivity test. Can only be present for device types collected via SSH.
    """
    discovered_cli_credential_id: Annotated[
        str | None, Field(alias="discoveredCliCredentialId", examples=["L-3"])
    ] = None
    """
    The `id` of the working CliCredential of type `LOGIN` auto-discovered during the connectivity test. Can only
    be present for device types collected via SSH.
    """
    discovered_http_credential_id: Annotated[
        str | None, Field(alias="discoveredHttpCredentialId", examples=["H-5"])
    ] = None
    """
    The `id` of the working HttpCredential of type `LOGIN` or `API_KEY` auto-discovered during the connectivity
    test. Can only be present for device types collected via HTTPS.
    """
    discovered_snmp_credential_id: Annotated[
        str | None, Field(alias="discoveredSnmpCredentialId", examples=["S-1"])
    ] = None
    """
    The `id` of the working SnmpCredential auto-discovered during the connectivity test.
    """
    discovered_type: Annotated[
        ClassicDeviceType | None, Field(alias="discoveredType", examples=["arista_eos_ssh"])
    ] = None
    """
    The device type auto-discovered during the connectivity test.
    """
    end_time: Annotated[str, Field(alias="endTime", examples=["2025-05-28T12:33:33.333Z"])]
    """
    When this connectivity test ended, according to the Collector’s system clock.
    """
    error: Annotated[ConnectivityTestError | None, Field(examples=["PING_FAILED"])] = None
    """
    The error encountered during the test. Present if the test failed. Absent if the test passed.
    """
    error_phase: Annotated[
        ErrorPhase | None, Field(alias="errorPhase", examples=["CONNECTION"])
    ] = None
    """
    The test phase during which `error` was encountered. Present if `error` is present.
    """
    host_ips: Annotated[list[str] | None, Field(alias="hostIps", examples=[["10.121.7.13"]])] = None
    """
    The IP addresses to which `host` resolves if it’s a hostname. Contains just `host` itself if it’s an IP
    address.
    """
    saved_at: Annotated[str, Field(alias="savedAt", examples=["2025-05-28T12:34:56.789Z"])]
    """
    When this connectivity test result was saved to the database, according to the server’s system
    clock.
    """
    start_time: Annotated[str, Field(alias="startTime", examples=["2025-05-28T12:33:00.000Z"])]
    """
    When this connectivity test began, according to the Collector’s system clock.
    """
    unauthorized_commands: Annotated[
        list[str] | None,
        Field(alias="unauthorizedCommands", examples=[["show config", "show interfaces status"]]),
    ] = None
    """
    Commands that failed with an authorization (permission) error during the connectivity test.
    """


