class CveOsInfo(ForwardModel):
    model_config = ConfigDict(
        extra="allow",
        populate_by_name=True,
    )
    advisory_mentions_exploit: Annotated[bool | None, Field(alias="advisoryMentionsExploit")] = None
    """
    Whether the vendor advisory at `url` says there’s a known exploit. Included only if true.
    """
    config_analysis: Annotated[ConfigAnalysis | None, Field(alias="configAnalysis")] = None
    """
    Present and can be any allowed value if `configDependent` is true. Absent if `configDependent` is false.
    Can be either "UNSUPPORTED" or absent if `configDependent` is absent (unknown).
    """
    config_dependent: Annotated[bool | None, Field(alias="configDependent")] = None
    """
    Whether this vulnerability depends on a device’s configuration for this OS. Absent if unknown.
    """
    os: VulnerabilityVendorOs
    publish_date: Annotated[str | None, Field(alias="publishDate", examples=["2023-12-31"])] = None
    """
    Publication date of the information at `url` if known.
    """
    severity: Severity
    """
    Severity based on one of this vulnerability’s CVSS scores according to the [Qualitative Severity
    Ratings](https://nvd.nist.gov/vuln-metrics/cvss#:~:text=Qualitative%20Severity%20Ratings) table. The priority
    order of scores is `v4Score`, then `v3Score`, then `v2Score`. "NONE" if no CVSS score is available for this
    vulnerability.
    """
    url: Annotated[
        str | None,
        Field(examples=["https://www.a10networks.com/blog/cve-2016-0270-gcm-nonce-vulnerability"]),
    ] = None
    """
    URL of this vulnerability’s vendor advisory, if available, or else the URL of the best source of information
    about the vulnerability that’s currently available.
    """
    v2_score: Annotated[float | None, Field(alias="v2Score", examples=[6.1])] = None
    """
    Score assigned by the Common Vulnerability Scoring System ([CVSS](https://nvd.nist.gov/vuln-metrics/cvss))
    v2.0 standard.
    """
    v3_score: Annotated[float | None, Field(alias="v3Score", examples=[9.8])] = None
    """
    Score assigned by the Common Vulnerability Scoring System ([CVSS](https://nvd.nist.gov/vuln-metrics/cvss))
    v3.x standard.
    """
    v4_score: Annotated[float | None, Field(alias="v4Score", examples=[8.4])] = None
    """
    Score assigned by the Common Vulnerability Scoring System
    ([CVSS](https://www.first.org/cvss/v4.0/specification-document)) v4.0 standard.
    """
    vendor: VulnerabilityVendor


