class NqeExecutionStatus(ForwardModel):
    model_config = ConfigDict(
        extra="allow",
        populate_by_name=True,
    )
    error: NqeQueryError | None = None
    """
    Diagnostic output describing why the query failed. Present only when `outcome` is `USER_ERROR`.
    """
    millis_executing: Annotated[int | None, Field(alias="millisExecuting")] = None
    """
    The total time, in milliseconds, that the query has spent executing. This timer starts when
    `status` transitions to `EXECUTING` and does not include any time spent queued beforehand. Absent when
    `status` is `SUBMITTED`.
    """
    outcome: Outcome | None = None
    """
    The outcome of the query execution. Present only when `status` is `COMPLETED`.
    - `OK`: the execution finished successfully and produced a result. The result can be retrieved using
      [Get NQE query execution result](https://docs.fwd.app/latest/api/nqe/get-nqe-execution-result/).
    - `USER_ERROR`: the execution terminated due to an error in the query itself (for example, a runtime error
      in the NQE code). See `error` for diagnostic information.
    - `TIMED_OUT`: the execution was automatically terminated because it exceeded `timeoutMinutes`.
    - `SYSTEM_ERROR`: the execution terminated due to an unexpected internal error.
    """
